1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * The single derived identity of an owner used for duplicate detection.
5	 *
6	 * <p>The {@code identityKey} consolidates the former separate telephone, email and household
7	 * duplicate checks into ONE value: {@code normalizedTelephone + '|' + (email or empty) + '|' +
8	 * householdId}. Two owners are duplicates only when their WHOLE key is equal, so — because the
9	 * telephone is part of the key — two members of the same household (same {@code householdId})
10	 * with different telephones have different keys and are both allowed.
11	 *
12	 * <ul>
13	 *   <li>telephone — normalized to E.164 with {@link NormalizeOwnerTelephone#toE164(String)} so
14	 *       equivalent numbers in different formats collide; the raw value is used only as a
15	 *       fallback when it cannot form a valid E.164 number.</li>
16	 *   <li>email — lower-cased so addresses differing only in case collide; a null or blank email
17	 *       contributes an empty segment.</li>
18	 *   <li>householdId — the shared household identifier, or an empty segment when the owner is not
19	 *       part of a household.</li>
20	 * </ul>
21	 */
22	public final class OwnerIdentity {
23	
24	    private OwnerIdentity() {
25	    }
26	
27	    /** Builds the {@code telephone|email|householdId} identity key. */
28	    public static String identityKey(String telephone, String email, String householdId) {
29	        String tel = NormalizeOwnerTelephone.toE164(telephone);
30	        if (tel == null) {
31	            tel = telephone == null ? "" : telephone;
32	        }
33	        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase();
34	        String hh = householdId == null ? "" : householdId;
35	        return tel + "|" + mail + "|" + hh;
36	    }
37	}
