1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerTelephoneDuplicateException;
8	
9	/**
10	 * Rejects the create when the E.164 telephone published by {@link NormalizeOwnerTelephone}
11	 * is already used by another owner. Existing owners' telephones are converted to E.164 the
12	 * same way before comparison, so equivalent numbers in different formats collide.
13	 * A match is rejected 409 via {@link OwnerTelephoneDuplicateException}.
14	 */
15	public class RequireUniqueOwnerTelephone {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws OwnerTelephoneDuplicateException {
19	        String telephone = request.getTelephone();
20	        for (Owner existing : ownerRepository.findAll()) {
21	            String other = NormalizeOwnerTelephone.toE164(existing.getTelephone());
22	            if (other != null && other.equals(telephone)) {
23	                throw new OwnerTelephoneDuplicateException(telephone);
24	            }
25	        }
26	    }
27	}
