1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerHouseholdDuplicateException;
8	
9	/**
10	 * Rejects the create when another owner already shares this owner's household: the same
11	 * {@code lastName} and {@code address}, compared case-insensitively with runs of whitespace
12	 * collapsed to a single space. A match is rejected 409 via
13	 * {@link OwnerHouseholdDuplicateException}.
14	 *
15	 * <p>Bypassed when the request sets {@code sharesHousehold} true — the caller has confirmed
16	 * the two owners knowingly live together.
17	 */
18	public class RequireUniqueOwnerHousehold {
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws OwnerHouseholdDuplicateException {
22	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
23	            return;
24	        }
25	        String lastName = normalize(request.getLastName());
26	        String address = normalize(request.getAddress());
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (normalize(existing.getLastName()).equals(lastName)
29	                    && normalize(existing.getAddress()).equals(address)) {
30	                throw new OwnerHouseholdDuplicateException(request.getLastName(),
31	                        request.getAddress());
32	            }
33	        }
34	    }
35	
36	    /** Lower-case, trimmed, with internal whitespace runs collapsed to a single space. */
37	    static String normalize(String value) {
38	        if (value == null) {
39	            return "";
40	        }
41	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
42	    }
43	}
