1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsMissingException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * First step of the create-owner pipeline: rejects a body that is missing or blank in
13	 * any required field (firstName, lastName, address, city, telephone) with a 400 whose
14	 * {@code errors} array names each offending field. Runs before {@link BuildOwner}, which
15	 * reads the published body via {@code @Val}.
16	 */
17	public class RequireOwnerFields {
18	
19	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
20	            throws OwnerFieldsMissingException {
21	        List<String> errors = new ArrayList<>();
22	        checkPresent("firstName", request.getFirstName(), errors);
23	        checkPresent("lastName", request.getLastName(), errors);
24	        // Address is required after normalization: a value that is blank once trimmed and
25	        // collapsed (see NormalizeOwnerAddress) is rejected here, not stored empty.
26	        if (NormalizeOwnerAddress.normalize(request.getAddress()).isEmpty()) {
27	            errors.add("address");
28	        }
29	        checkPresent("city", request.getCity(), errors);
30	        checkPresent("telephone", request.getTelephone(), errors);
31	        if (!errors.isEmpty()) {
32	            throw new OwnerFieldsMissingException(errors);
33	        }
34	        validated.set(request);
35	    }
36	
37	    private static void checkPresent(String field, String value, List<String> errors) {
38	        if (value == null || value.isBlank()) {
39	            errors.add(field);
40	        }
41	    }
42	}
