9	/**
10	 * Maps the validated body (published by {@link RequireOwnerFields}) to a new {@link Owner}.
11	 * When the body supplies no registration date, defaults it to the server's current date; either
12	 * way the effective date is rolled forward off any weekend to the next business day, so every
13	 * later step (membership number, daily limit) sees the adjusted {@code registrationDate}.
14	 */
15	public class BuildOwner {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
18	        Owner owner = ownerMapper.toOwner(request);
19	        owner.setRegistrationDate(RegistrationDate.effective(request));
20	        built.set(owner);
21	    }
22	}
