3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerEmailDuplicateException;
8	
9	/**
10	 * Rejects the create when the email published by {@link NormalizeOwnerEmail} is already used
11	 * by another owner. Email is optional: a null or blank value skips the check. Both the request
12	 * email and existing owners' emails are compared lower-cased, so addresses differing only in
13	 * case collide. A match is rejected 409 via {@link OwnerEmailDuplicateException}.
14	 */
15	public class RequireUniqueOwnerEmail {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws OwnerEmailDuplicateException {
19	        String email = request.getEmail();
20	        if (email == null || email.isBlank()) {
21	            return;
22	        }
23	        String normalized = email.toLowerCase();
24	        for (Owner existing : ownerRepository.findAll()) {
25	            String other = existing.getEmail();
26	            if (other != null && other.toLowerCase().equals(normalized)) {
27	                throw new OwnerEmailDuplicateException(normalized);
28	            }
29	        }
30	    }
31	}
