1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	/**
4	 * Thrown by the create-owner pipeline when a new owner's WHOLE derived {@code identityKey}
5	 * (telephone|email|householdId) equals an existing owner's, i.e. it is a full duplicate.
6	 *
7	 * <p>Carries the identity key so {@link OwnerIdentityDuplicateExceptionHandler} can respond 409
8	 * explaining why the create was rejected.
9	 */
10	public class OwnerIdentityDuplicateException extends Exception {
11	
12	    private final String identityKey;
13	
14	    public OwnerIdentityDuplicateException(String identityKey) {
15	        super("Owner identity '" + identityKey + "' is already used by another owner");
16	        this.identityKey = identityKey;
17	    }
18	
19	    public String getIdentityKey() {
20	        return identityKey;
21	    }
22	}
