1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	import java.util.List;
4	import java.util.Map;
5	
6	import net.officefloor.plugin.section.clazz.Parameter;
7	import net.officefloor.web.ObjectResponse;
8	import org.springframework.http.HttpStatus;
9	import org.springframework.http.ResponseEntity;
10	
11	/**
12	 * Responds 409 with a JSON body {@code {"errors": ["identityKey"]}} when a new owner's whole
13	 * derived {@code identityKey} matches an existing owner's.
14	 */
15	public class OwnerIdentityDuplicateExceptionHandler {
16	
17	    public void handle(@Parameter OwnerIdentityDuplicateException ex,
18	            ObjectResponse<ResponseEntity<Map<String, Object>>> response) {
