1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.OwnerTelephoneInvalidException;
6	
7	/**
8	 * Normalizes the telephone of the validated body (published by {@link RequireOwnerFields})
9	 * into E.164 form: spaces, dashes and brackets are stripped; a leading {@code '+'} with its
10	 * country code is kept when present, otherwise country code {@code '+61'} is assumed and a
11	 * single leading {@code '0'} is dropped from the national digits. The result must have 8 to
12	 * 15 digits after the {@code '+'}, and the national-number length must match the country code
13	 * ({@code '+61'} requires 9 national digits, {@code '+1'} requires 10). The E.164 value is
14	 * written back onto the body in place, so
15	 * {@link BuildOwner} maps it and later reads/responses return it. A telephone that cannot form
16	 * a valid E.164 number is rejected 400 via {@link OwnerTelephoneInvalidException}.
17	 */
18	public class NormalizeOwnerTelephone {
19	
20	    public void service(@Val OwnerFieldsDto request) throws OwnerTelephoneInvalidException {
21	        String raw = request.getTelephone();
22	        String e164 = toE164(raw);
23	        if (e164 == null) {
24	            throw new OwnerTelephoneInvalidException(raw == null ? "" : raw);
25	        }
26	        request.setTelephone(e164);
27	    }
28	
29	    /**
30	     * Converts a telephone into E.164 form, or returns {@code null} when it cannot form a
31	     * valid E.164 number. Shared with {@link RequireUniqueOwnerTelephone} so stored and new
32	     * telephones are compared in the same canonical form.
33	     */
34	    static String toE164(String raw) {
35	        if (raw == null) {
36	            return null;
37	        }
38	        // Strip spaces, dashes and brackets (leave a leading '+' and the digits).
39	        String cleaned = raw.replaceAll("[\\s\\-()]", "").trim();
40	        String digits;
41	        if (cleaned.startsWith("+")) {
42	            // Explicit country code: keep the digits following the '+'.
43	            digits = cleaned.substring(1);
44	        } else {
45	            // No country code: assume '+61', dropping a single leading '0'.
46	            String national = cleaned;
47	            if (national.startsWith("0")) {
48	                national = national.substring(1);
49	            }
50	            digits = "61" + national;
51	        }
52	        if (!digits.matches("\\d{8,15}")) {
53	            return null;
54	        }
55	        // Country-specific national-number length: '+61' requires 9 national digits,
56	        // '+1' requires 10. Other country codes keep only the general 8-15 rule above.
57	        if (digits.startsWith("61")) {
58	            if (digits.length() - 2 != 9) {
59	                return null;
60	            }
61	        } else if (digits.startsWith("1")) {
62	            if (digits.length() - 1 != 10) {
63	                return null;
64	            }
65	        }
66	        return "+" + digits;
67	    }
68	}
