1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerPostcodeInvalidException;
8	
9	/**
10	 * Validates the owner's optional {@code postcode} WHEN PRESENT. A supplied postcode must be
11	 * exactly four digits and, when the owner's city maps to a known region, must fall within that
12	 * region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
13	 * region accepts any four-digit postcode. An absent postcode is left untouched — postcode is
14	 * optional, so the request contract stays backward-compatible.
15	 *
16	 * <p>Reads the body published by {@link RequireOwnerFields}; runs before {@link BuildOwner} so an
17	 * out-of-range postcode is a 400 via {@link OwnerPostcodeInvalidException}, never stored.
18	 */
19	public class RequireOwnerPostcode {
20	
21	    /** City -> region, using the same fixed table as the owner locality mapping. */
22	    private static final Map<String, String> CITY_REGION =
23	            Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
24	
25	    /** Region -> inclusive {low, high} 4-digit postcode range. */
26	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
27	            "NSW", new int[] {2000, 2099},
28	            "VIC", new int[] {3000, 3099},
29	            "QLD", new int[] {4000, 4099});
30	
31	    public void service(@Val OwnerFieldsDto request) throws OwnerPostcodeInvalidException {
32	        String postcode = request.getPostcode();
33	        if (postcode == null) {
34	            return; // optional when absent
35	        }
36	        if (!postcode.matches("[0-9]{4}")) {
37	            throw new OwnerPostcodeInvalidException(postcode);
38	        }
39	        String region = CITY_REGION.get(request.getCity());
40	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
41	        if (range != null) {
42	            int value = Integer.parseInt(postcode);
43	            if (value < range[0] || value > range[1]) {
44	                throw new OwnerPostcodeInvalidException(postcode);
45	            }
46	        }
47	    }
48	}
