1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.rest.function.owner.OwnerRegion;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName",
23	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "initials",
25	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
26	    @Mapping(target = "locality",
27	        expression = "java(deriveLocality(owner))")
28	    @Mapping(target = "contactPreference",
29	        expression = "java(owner.getEmail() != null && !owner.getEmail().isBlank() ? \"EMAIL\" : \"PHONE\")")
30	    @Mapping(target = "identityKey",
31	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId()))")
32	    @Mapping(target = "checkDigit",
33	        expression = "java(luhnCheckDigit(owner.getCustomerCode()))")
34	    @Mapping(target = "ageBand",
35	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate()))")
36	    OwnerDto toOwnerDto(Owner owner);
37	
38	    Owner toOwner(OwnerDto ownerDto);
39	
40	    @Mapping(target = "id", ignore = true)
41	    @Mapping(target = "pets", ignore = true)
42	    Owner toOwner(OwnerFieldsDto ownerDto);
43	
44	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
45	
46	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
47	
48	    /**
49	     * Derives the owner's locality (region) from the region-and-hash identity: the {@code <REGION>}
50	     * segment of the {@code <REGION>-<HASH8>} {@code customerCode}. The region embedded in the code
51	     * is itself derived (postcode preferred, then city) when the owner is created, so a postcode in a
52	     * known range still wins over the city. When no such code is present (e.g. legacy owners), falls
53	     * back to deriving the region live from the postcode/city via {@link OwnerRegion}.
54	     */
55	    default String deriveLocality(Owner owner) {
56	        String code = owner.getCustomerCode();
57	        if (code != null) {
58	            int dash = code.indexOf('-');
59	            if (dash > 0) {
60	                return code.substring(0, dash);
61	            }
62	        }
63	        return OwnerRegion.fromPostcodeOrCity(owner.getPostcode(), owner.getCity());
64	    }
65	
66	    /**
67	     * Computes the single Luhn check digit (0-9) over the digits contained in the given
68	     * customerCode. Non-digit characters (the separators) are ignored; from the rightmost digit
69	     * leftwards every second digit is doubled (subtracting 9 when the result exceeds 9), and the
70	     * check digit is {@code (10 - (sum % 10)) % 10}. Returns 0 when the code is null.
71	     */
72	    default int luhnCheckDigit(String customerCode) {
73	        if (customerCode == null) {
74	            return 0;
75	        }
76	        int sum = 0;
77	        boolean dbl = true;
78	        for (int i = customerCode.length() - 1; i >= 0; i--) {
79	            char c = customerCode.charAt(i);
80	            if (c < '0' || c > '9') {
81	                continue;
82	            }
83	            int d = c - '0';
84	            if (dbl) {
85	                d *= 2;
86	                if (d > 9) {
87	                    d -= 9;
88	                }
89	            }
90	            sum += d;
91	            dbl = !dbl;
92	        }
93	        return (10 - (sum % 10)) % 10;
94	    }
95	
96	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
97	        OwnerPageDto ownerPageDto = new OwnerPageDto();
98	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
99	        ownerPageDto.setPage(ownerPage.getNumber());
100	        ownerPageDto.setSize(ownerPage.getSize());
101	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
102	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
103	        return ownerPageDto;
104	    }
105	}
